"use strict";
// gen-classes.mjs -- class generator for Leap Desktop (docs/OBJECTS_EVENTS.md sections 3 and 13.2).
//   node tools/gen-classes.mjs <outDir> <classfile>...     CLI, for debugging
// genClasses(files, outDir) reads the class files in order (a class's parent may be in an earlier file), writes
// <outDir>/<basename>.inc for each file and <outDir>/classes.json for all of them; returns the written paths.
// Generated files are never hand-edited.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { basename, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/;

function poolOf(size) { return size <= 8 ? 6 : size <= 16 ? 8 : size <= 24 ? 10 : size <= 32 ? 12 : 14; }

/** Parse and resolve the class files; returns { classes (definition order), messages, perFile }. */
export function parseClasses(files) {
  const classes = [], byName = new Map(), msgOwner = new Map();   // msgOwner: message NAME -> class name that defines it
  const perFile = [];
  for (const file of files) {
    const err = (ln, msg) => { throw new Error(`${file}:${ln}: ${msg}`); };
    const lines = readFileSync(file, 'utf8').split(/\r?\n/);
    const mine = { file, classes: [], messages: [] };
    perFile.push(mine);
    let cur = null;
    lines.forEach((raw, i) => {
      const ln = i + 1;
      const text = raw.replace(/#.*/, '').trim();
      if (!text) return;
      const w = text.split(/\s+/);
      if (w[0] === 'class') {
        // class Name   |   class Name : Parent   (the colon may or may not be spaced)
        const m = text.match(/^class\s+(\S+?)\s*(?::\s*(\S+))?\s*$/);
        if (!m || !IDENT.test(m[1]) || (m[2] !== undefined && !IDENT.test(m[2]))) err(ln, `malformed class line: "${text}"`);
        const [, name, parentName] = m;
        if (byName.has(name)) err(ln, `duplicate class ${name}`);
        let parent = null;
        if (parentName !== undefined) {
          parent = byName.get(parentName);
          if (!parent) {
            // distinguish "defined later" from "unknown"
            const later = files.some(f => readFileSync(f, 'utf8').split(/\r?\n/)
              .some(l => new RegExp(`^\\s*class\\s+${parentName}\\b`).test(l.replace(/#.*/, ''))));
            err(ln, later ? `parent ${parentName} of ${name} is defined later` : `unknown parent ${parentName} of ${name}`);
          }
        }
        cur = {
          name, id: classes.length + 1, parent: parent ? parent.name : null,
          size: parent ? parent.size : 2, pool: 0,
          fields: [], allFields: parent ? parent.allFields.slice() : [],
          methods: parent ? parent.methods.map(m => ({ ...m })) : [],   // flattened, slot order
          own: new Set(), line: ln, file,
        };
        classes.push(cur); byName.set(name, cur); mine.classes.push(cur);
      } else if (w[0] === 'field') {
        if (!cur) err(ln, 'field before any class');
        if (w.length !== 3 || !IDENT.test(w[1]) || !/^\d+$/.test(w[2])) err(ln, `malformed field line: "${text}"`);
        const size = Number(w[2]);
        if (size < 1 || size > 253) err(ln, `field ${cur.name}.${w[1]}: size ${size} out of 1..253`);
        if (cur.allFields.includes(w[1])) err(ln, `duplicate field ${w[1]} in ${cur.name}`);
        cur.fields.push({ name: w[1], offset: cur.size, size });
        cur.allFields.push(w[1]);
        cur.size += size;
        if (cur.size > 255) err(ln, `class ${cur.name}: instance size ${cur.size} over 255`);
      } else if (w[0] === 'method') {
        if (!cur) err(ln, 'method before any class');
        if (w.length !== 3 || !IDENT.test(w[1]) || !IDENT.test(w[2])) err(ln, `malformed method line: "${text}"`);
        const [, name, label] = w;
        if (cur.own.has(name)) err(ln, `duplicate method ${name} in ${cur.name}`);
        cur.own.add(name);
        const slot = cur.methods.find(m => m.name === name);
        if (slot) { slot.label = label; }                         // override: an ancestor defines the name
        else {
          const key = name.toUpperCase();
          if (msgOwner.has(key)) err(ln, `message ${name} is already defined as new in ${msgOwner.get(key)}`);
          msgOwner.set(key, cur.name);
          if (cur.methods.length >= 127) err(ln, `class ${cur.name}: more than 127 methods`);
          cur.methods.push({ n: cur.methods.length, name, label });
          mine.messages.push({ name: key, n: cur.methods.length - 1 });
        }
      } else err(ln, `malformed line: "${text}"`);
    });
  }
  for (const c of classes) c.pool = poolOf(c.size);
  const messages = {};
  for (const [key, owner] of msgOwner) messages[key] = byName.get(owner).methods.find(m => m.name.toUpperCase() === key).n;
  return { classes, messages, perFile };
}

function incText(f) {
  const out = [`; ${basename(f.file)}: GENERATED by tools/gen-classes.mjs, do not edit`];
  for (const c of f.classes) {
    const n = c.methods.length;
    out.push('',
      `; class ${c.name}${c.parent ? ' : ' + c.parent : ''}`,
      `    IF ((($ + 6) & $FF) + 2 * ${n}) > 256    ; the method table must not cross a page`,
      `    ALIGN 256, 0`,
      `    ENDIF`,
      `    DW ${c.parent ? 'CL_' + c.parent : '0'}`,
      `    DB ${c.id}, ${n}, ${c.size}, ${c.pool}`,
      `CL_${c.name}:`,
      `    DW ${c.methods.map(m => m.label).join(', ')}`);
  }
  out.push('');
  for (const m of f.messages) out.push(`M_${m.name} EQU ${m.n}`);
  for (const c of f.classes) {
    for (const fl of c.fields) out.push(`${c.name}_${fl.name} EQU ${fl.offset}`);
    out.push(`${c.name}_SIZE EQU ${c.size}`);
  }
  return out.join('\n') + '\n';
}

/** Generate; returns the list of written paths (the .inc files, then classes.json). */
export function genClasses(files, outDir) {
  const { classes, messages, perFile } = parseClasses(files);
  mkdirSync(outDir, { recursive: true });
  const written = [];
  for (const f of perFile) {
    const p = join(outDir, basename(f.file).replace(/\.[^.]*$/, '') + '.inc');
    writeFileSync(p, incText(f));
    written.push(p);
  }
  const json = {
    messages,
    classes: classes.map(c => ({
      name: c.name, id: c.id, parent: c.parent, size: c.size, pool: c.pool, fields: c.fields,
      methods: c.methods.map(m => ({ n: m.n, name: m.name, label: m.label })),
    })),
  };
  const jp = join(outDir, 'classes.json');
  writeFileSync(jp, JSON.stringify(json, null, 2) + '\n');
  written.push(jp);
  return written;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const [outDir, ...files] = process.argv.slice(2);
  if (!outDir || !files.length) { console.error('usage: node tools/gen-classes.mjs <outDir> <classfile>...'); process.exit(2); }
  try { for (const p of genClasses(files, outDir)) console.log(p); }
  catch (e) { console.error(e.message); process.exit(1); }
}
